package tritium.minecraft.runtime.render;
import org.lwjgl.opengl.*;
import tritium.minecraft.runtime.hook.RenderAccess;
import tritium.minecraft.runtime.util.render.*;
public final class PlayerESPModule extends RenderModule {
 public boolean shaderPass;
 private Framebuffer framebuffer;private final EspShaders shaders;private GlowShader glow;
 private static final int[] MODES={0,-1,-2,-3,1,2,3,6};
 public PlayerESPModule(RenderAccess g,Render3D d){super("playerESP",g,d);shaders=new EspShaders(g,d);}
 private boolean active(){return enabled&&(!on("Disable in lobby")||!g.lobby);}
 public int color(Object e,float pt){int c;if(on("Team color")){c=-1;Object team=g.invoke(e,"getTeam");if(team!=null){String prefix=String.valueOf(g.invoke(g.cls("client.gui.FontRenderer"),"getFormatFromString",g.invoke(team,"getColorPrefix")));if(prefix.length()>=2)c=0xff000000|RenderAccess.i(g.invoke(g.font(),"getColorCode",prefix.charAt(1)))&0xffffff;}}else c=on("Rainbow")?0:rgb();if(on("Red on damage")&&g.value(e,"hurtTime")>1){if(c==0)c=Render3D.rainbow(2);double mix=Math.max(0,Math.min(1,(g.value(e,"hurtTime")-pt-1)/7));c=RenderShapes.blendInt(Theme.FLARE.first.getRGB(),c,mix);}return c;}
 private boolean accepted(Object e,boolean shader){if(e==g.player()&&!shader)return on("Render self")&&g.integerField(g.settings(),"thirdPersonView")!=0&&!RenderAccess.b(g.invoke(e,"isPlayerSleeping"));if(g.integerField(e,"deathTime")!=0||!on("Show invis")&&g.invisible(e)||g.aboveSpawn(e))return false;if(!shader&&!draw.visible(e))return false;if(g.bot(e))return false;if(e==g.player())return on("Render self")&&g.integerField(g.settings(),"thirdPersonView")!=0&&!RenderAccess.b(g.invoke(e,"isPlayerSleeping"));return true;}
 public void world(float pt){if(!active())return;int mode=MODES[(int)n("Type")];if(mode<0)shader(pt,mode);for(Object e:g.players()){if(!accepted(e,false))continue;int c=color(e,pt);if(on("Health bar"))draw.entity(e,4,c,pt);if(mode>0)draw.entity(e,mode,c,pt);}}
 private void shader(float pt,int mode){if(!shaders.valid(shaders.outline())||!shaders.valid(shaders.fill()))return;if(framebuffer==null||framebuffer.framebufferWidth!=g.displayWidth()||framebuffer.framebufferHeight!=g.displayHeight()){if(framebuffer!=null)framebuffer.deleteFramebuffer();framebuffer=new Framebuffer(g,g.displayWidth(),g.displayHeight(),false);framebuffer.setFramebufferFilter(GL11.GL_NEAREST);}Object rm=g.manager();boolean shadow=RenderAccess.b(g.invoke(rm,"isRenderShadow")),drew=false;int matrix=GL11.glGetInteger(GL11.GL_MATRIX_MODE);GL11.glMatrixMode(GL11.GL_PROJECTION);GL11.glPushMatrix();GL11.glMatrixMode(GL11.GL_MODELVIEW);GL11.glPushMatrix();try{framebuffer.framebufferClear();framebuffer.bindFramebuffer(false);draw.setupCamera(pt);g.invoke(rm,"setRenderShadow",false);g.state("disableLighting");g.state("disableBlend");g.state("enableAlpha");g.state("alphaFunc",516,.001f);g.state("depthMask",false);g.state("setActiveTexture",GL13.GL_TEXTURE1);g.state("disableTexture2D");g.state("setActiveTexture",GL13.GL_TEXTURE0);g.state("enableTexture2D");g.state("color",1f,1f,1f,1f);shaderPass=true;for(Object e:g.players()){if(!accepted(e,true))continue;int c=color(e,pt);if(c==0)c=Render3D.rainbow(2);shaders.useFill(c);g.invoke(rm,"renderEntityStatic",e,pt,true);shaders.fill().stop();drew=true;}shaderPass=false;g.invoke(g.renderer(),"disableLightmap");new Framebuffer(g,g.invoke(g.mc,"getFramebuffer")).bindFramebuffer(false);draw.overlay();if(drew){g.state("disableDepth");g.state("depthMask",false);g.state("disableLighting");g.state("disableCull");g.state("enableTexture2D");g.state("enableBlend");g.state("tryBlendFuncSeparate",770,771,1,0);g.state("color",1f,1f,1f,1f);if(mode!=-1){if(glow==null)glow=new GlowShader(g,draw);glow.render(framebuffer,2,mode==-2?1.5f:6.5f);}shaders.outline(framebuffer,2,.1f);}}finally{shaders.fill().stop();shaderPass=false;g.invoke(rm,"setRenderShadow",shadow);new Framebuffer(g,g.invoke(g.mc,"getFramebuffer")).bindFramebuffer(false);GL11.glMatrixMode(GL11.GL_MODELVIEW);GL11.glPopMatrix();GL11.glMatrixMode(GL11.GL_PROJECTION);GL11.glPopMatrix();GL11.glMatrixMode(matrix);g.state("setActiveTexture",GL13.GL_TEXTURE0);g.state("enableTexture2D");g.state("enableDepth");g.state("depthMask",true);g.state("enableCull");g.state("enableAlpha");g.state("alphaFunc",516,.1f);g.state("disableBlend");}}
 public void close(){if(framebuffer!=null){framebuffer.deleteFramebuffer();framebuffer=null;}shaders.close();if(glow!=null){glow.close();glow=null;}}
}
